    roles: ['PA', 'DA', 'PM', 'BA'],
    priority: 1,
    estimatedMin: 10,
    datamartId: 'ecomm',
    prompt: 'The growth team wants to understand which acquisition channels drive the most purchase sessions. For each channel, return channel, session_count, conversions (sessions where converted=1), and conversion_rate (rounded to 2 decimal places). Order by conversion_rate descending.',
    expectedColumns: ['channel', 'session_count', 'conversions', 'conversion_rate'],
