    prompt: 'The compliance team\'s open dispute dashboard has been showing zero open disputes for two weeks. They assumed all disputes had been resolved and closed the review cycle. Three disputes are actually still open. Find the bug and write the corrected query.',
    brokenQuery: 'SELECT dispute_id, amount, opened_at\nFROM disputes\nWHERE resolved_at = NULL\nORDER BY amount DESC',
