    solution: 'SELECT u.user_id, u.email, COUNT(o.order_id) AS orders_2024\nFROM users u\nLEFT JOIN orders o ON u.user_id = o.user_id\n  AND o.created_at >= \'2024-01-01\'\nGROUP BY u.user_id, u.email\nORDER BY u.user_id',
