    checkValues: [{ name: 'TechVault' }],
    solution: 'SELECT s.name, s.tier,\n  COALESCE(SUM(CASE WHEN t.status = \'completed\' THEN t.sale_price END), 0) AS total_gmv,\n  ROUND(AVG(r.rating), 1) AS avg_rating,\n  DENSE_RANK() OVER (ORDER BY COALESCE(SUM(CASE WHEN t.status = \'completed\' THEN t.sale_price END), 0) DESC) AS gmv_rank\nFROM sellers s\nLEFT JOIN transactions t ON s.seller_id = t.seller_id\nLEFT JOIN reviews r ON s.seller_id = r.seller_id\nGROUP BY s.seller_id, s.name, s.tier\nORDER BY gmv_rank',
